// Gabungkan label AI dengan pesannya, lalu BUANG teksnya.
// Yang keluar dari node ini hanya: bulan, user, topik, hitungan, rentang waktu.
const batches = $('Prepare Batches').all().map(function (i) { return i.json; });
const responses = $input.all().map(function (i) { return i.json; });

function bulanWIB(ts) {
  const d = new Date(Number(ts));
  const parts = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Asia/Jakarta', year: 'numeric', month: '2-digit'
  }).formatToParts(d);
  const y = parts.find(function (p) { return p.type === 'year'; }).value;
  const m = parts.find(function (p) { return p.type === 'month'; }).value;
  return y + '-' + m;
}

function parseLabels(resp) {
  try {
    const content = resp && resp.content;
    if (!Array.isArray(content) || !content.length) return null;
    let text = '';
    for (const c of content) { if (c && c.type === 'text') text += c.text; }
    text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const parsed = JSON.parse(text);
    return Array.isArray(parsed) ? parsed : null;
  } catch (e) { return null; }
}

const agg = {};
let classified = 0, failedBatches = 0, newTopics = 0;

for (let b = 0; b < batches.length; b++) {
  const batch = batches[b];
  const labels = parseLabels(responses[b]);

  if (!labels) {
    // Batch gagal diparse. Jangan tebak — biarkan tidak terhitung.
    failedBatches++;
    continue;
  }

  const byIndex = {};
  for (const l of labels) {
    if (l && l.i != null) byIndex[Number(l.i)] = String(l.topic || '').trim();
  }

  for (let n = 0; n < batch.items.length; n++) {
    const it = batch.items[n];
    let topic = byIndex[n] || '';
    if (!topic) topic = 'lainnya';
    if (topic.indexOf('NEW:') === 0) newTopics++;

    const bulan = bulanWIB(it.ts);
    const rowKey = bulan + '|' + it.key + '|' + topic;

    if (!agg[rowKey]) {
      agg[rowKey] = {
        row_key: rowKey, bulan: bulan, user_key: it.key, topic: topic,
        jumlah_pesan: 0, first_ts: it.ts, last_ts: it.ts
      };
    }
    const a = agg[rowKey];
    a.jumlah_pesan += 1;
    if (it.ts < a.first_ts) a.first_ts = it.ts;
    if (it.ts > a.last_ts) a.last_ts = it.ts;
    classified++;
  }
}

// Kalau SEMUA batch gagal, jangan majukan watermark — biar dicoba lagi run berikutnya.
if (failedBatches === batches.length) {
  throw new Error('Semua batch gagal diklasifikasi (' + failedBatches + '). Watermark tidak dimajukan.');
}

const rows = Object.keys(agg).map(function (k) { return agg[k]; });
const meta = {
  new_watermark: batches[0].new_watermark,
  batches_total: batches.length,
  batches_failed: failedBatches,
  classified: classified,
  new_topic_hits: newTopics
};

return rows.map(function (r) { return { json: Object.assign({}, r, { _meta: meta }) }; });

// Tambahkan hitungan lama dari TOPIC_LOG supaya appendOrUpdate tidak menimpa histori.
const existing = {};
for (const item of $('Read TOPIC_LOG').all()) {
  const r = item.json || {};
  const k = String(r.row_key || '').trim();
  if (!k) continue;
  existing[k] = {
    jumlah_pesan: Number(r.jumlah_pesan) || 0,
    first_ts: Number(r.first_ts) || 0,
    last_ts: Number(r.last_ts) || 0
  };
}

// PENTING: baris agregat diambil dari $('Aggregate'), BUKAN $input.
// Di n8n, $input sebuah node = output node TEPAT SEBELUMNYA -- di sini itu
// "Read TOPIC_LOG" (isi sheet), bukan hasil Aggregate. Memakai $input di sini
// membuat baris yang ditulis kosong semua.
return $('Aggregate').all().map(function (item) {
  const r = Object.assign({}, item.json);
  const prev = existing[r.row_key];
  if (prev) {
    r.jumlah_pesan = prev.jumlah_pesan + r.jumlah_pesan;
    if (prev.first_ts && prev.first_ts < r.first_ts) r.first_ts = prev.first_ts;
    if (prev.last_ts && prev.last_ts > r.last_ts) r.last_ts = prev.last_ts;
  }
  return { json: r };
});
